Definition inZ (r : Z * Z) (z : Z) : Prop := fst r <= z < snd r.
Fixpoint inZs (rs : list (Z * Z)) (z : Z) : Prop :=
  match rs with [] => False | r :: t => inZ r z \/ inZs t z end.

