(* [comment removed for export] *)
Lemma W_store_blk : forall C A m md (p a : word) (n : Z) bs, Cok C -> W C A m md ->
  live A p = Some n -> live (c_A0 C) p = None ->
  u p <= u a -> u a + Z.of_nat (length bs) <= u p + n ->
  W C A (wbytes m a bs) md.
Proof.
