Definition LIVK (A : AS) (m m' : word -> option byte) : Prop :=
  forall q k i, live A q = Some k -> 0 <= i < k -> m' (at_ q i) = m (at_ q i).
Definition POSTM (C : lctx) (A : AS) (s : Z) (m m' : word -> option byte) : Prop := FRM C s m m' /\ LIVK A m m'.
