Lemma WP_blk : forall C A A' mb m md (p a : word) (n : Z) bs (s : Z), Cok C ->
  W C A' m md /\ POSTM C A s mb m ->
  live A' p = Some n -> live A p = None -> live (c_A0 C) p = None -> sub_live A A' ->
  u p <= u a -> u a + Z.of_nat (length bs) <= u p + n ->
