Lemma W_rdn_clr : forall C A m md (a : Z) (n : nat), W C A m md ->
  (forall z, a <= z < a + Z.of_nat n -> inZs ll_clr z) -> 0 <= a -> a + Z.of_nat n < 2 ^ 64 ->
